<script lang="ts">import {onMount} from 'svelte';import {api} from '../lib/api.js';let rows:any[]=[];let status='Loading metrics…';let root='';let contextId='local';let command='';let running=false;let output='';async function load(){try{const state=await api<any>('/api/state');if(!state.index){status='Analyze a repository to populate function metrics.';return}const graph=await api<any>('/api/graph?type=function&limit=10000');root=graph.index.root;contextId=graph.index.contextId;rows=graph.nodes.sort((a:any,b:any)=>(b.crap??-1)-(a.crap??-1));status=`${rows.length} functions`;const commands=await api<any>(`/api/coverage/commands?contextId=${encodeURIComponent(contextId)}&repositoryPath=${encodeURIComponent(root)}`).catch(()=>({commands:[]}));command=commands.commands?.[0]??''}catch(error){status=(error as Error).message}}async function refreshCoverage(){if(!command||running)return;running=true;status='Running coverage…';try{const result=await api<any>('/api/coverage/refresh',{method:'POST',body:JSON.stringify({contextId,repositoryPath:root,command})});output=result.output??'';status=result.coverage?.verified?'Coverage verified':'Coverage completed with stale evidence';await load()}catch(error){status=(error as Error).message}finally{running=false}}function open(row:any){window.dispatchEvent(new CustomEvent('atlas:open-file',{detail:{contextId,path:`${root}/${row.path}`.replaceAll('//','/'),pinned:true,line:row.line}}))}onMount(()=>{void load();const refresh=()=>void load();window.addEventListener('atlas:graph-refresh',refresh);return()=>window.removeEventListener('atlas:graph-refresh',refresh)})</script>
<section class="panel metrics-panel"><header><div><strong>Function metrics · CRAP</strong><span>{status}</span></div><div class="metric-actions"><input bind:value={command} aria-label="Coverage command" placeholder="coverage command"/><button onclick={refreshCoverage} disabled={!command||running} title="Run coverage in the selected FNGK context">{running?'Running…':'Refresh coverage'}</button></div></header>{#if output}<details class="run-output"><summary>Latest coverage output</summary><pre>{output}</pre></details>{/if}<div class="metrics-table"><table><thead><tr><th>Function</th><th>File</th><th>Lines</th><th>Complexity</th><th>Coverage</th><th>CRAP</th></tr></thead><tbody>{#each rows as row}<tr ondblclick={()=>open(row)}><td>{row.qualifiedName??row.label}</td><td>{row.path}:{row.line}</td><td>{row.physicalLines??'—'}</td><td>{row.complexity??'—'}</td><td>{row.coverage?`${Math.round(row.coverage.fraction*100)}%${row.coverage.stale?' stale':''}`:'—'}</td><td class:bad={row.crap>30}>{row.crap==null?'—':Number(row.crap).toFixed(1)}</td></tr>{/each}</tbody></table>{#if !rows.length}<div class="empty-copy">No function evidence yet. Choose a Device, set a repository path, and map code.</div>{/if}</div></section>
